// views/status.html → lib/status-page.generated.mjs
//
// The status page is served by a function behind a key, not from the static
// folder. A function can only be sure of the files it imports: Vercel traces
// imports, while a file read at run time depends on includeFiles being
// honoured and on which build step runs first. So the page is a module. The
// generated file is committed, because the builder that bundles api/ does not
// wait for the build command that could regenerate it; this runs in prebuild
// so the copy can never be older than the source.
import { readFileSync, writeFileSync } from 'node:fs';

const SRC = new URL('../views/status.html', import.meta.url);
const OUT = new URL('../lib/status-page.generated.mjs', import.meta.url);
const html = readFileSync(SRC, 'utf8');
const out = `// Generated by scripts/make-status-page.mjs from views/status.html — edit the HTML, not this.\nexport default ${JSON.stringify(html)};\n`;
writeFileSync(OUT, out);
console.log(`status page: ${Math.round(html.length / 1024)}KB → lib/status-page.generated.mjs`);
